// Consulta e administração da ficha

function lookup(selected) {
  const tag = $("#search").value.trim().toUpperCase();
  const color = $("#search-color").value;
  if (!tag || !color) {
    $(tag ? "#search-color" : "#search").focus();
    return toast(tag ? "⚠️ Selecione a cor do brinco." : "⚠️ Informe o brinco do animal.");
  }
  const matches = animalsWithTag(tag).filter(a => (a.tagColor || "sem-cor") === color);
  if (!matches.includes(selected) && matches.length > 1) return chooseAnimal(matches, lookup);
  const a = matches.includes(selected) ? selected : matches[0];
  if (!a) {
    $("#result").className = "empty";
    $("#result").textContent = "";
    $("#search").focus();
    return toast("⚠️ Animal não possui registro com este brinco e esta cor.");
  }
  $("#result").className = "";
  const w = sort(a);
  const minimum = w.reduce((min, point) => Math.min(min, point.kg), Infinity);
  const maximum = w.reduce((max, point) => Math.max(max, point.kg), -Infinity);
  $("#result").innerHTML =
    `<div class="row"><h2>Brinco ${esc(a.id)}</h2><span class="pill">${esc(cat(a))}</span></div><p>${esc(a.breed || "Raça não informada")} · Idade: ${esc(hasInfo(a.age) ? a.age : "não informada")} ${hasInfo(a.age) ? "meses" : ""} · Entrada: ${date(a.arrival)}</p>${entryDetails(a)}${exitSummary(a.exit)}${movementHistory(a)}${bathHistory(a)}<div class="grid"><div><h3>Histórico de pesagens</h3>${w.length > 1 ? `<svg class="chart" viewBox="0 0 400 120" role="img" aria-label="Evolução do peso"><polyline fill="none" stroke="#6e8d4e" stroke-width="3" points="${w.map((p, i) => `${10 + (i * 380) / (w.length - 1)},${100 - ((p.kg - minimum) * 80) / (maximum - minimum || 1)}`).join(" ")}"/></svg>` : ""}${w.map((r, i) => `<div class="row"><span>${date(r.day)}</span><b>${r.kg} kg</b><span>${i ? (r.kg - w[i - 1].kg).toFixed(1) + " kg" : "Primeiro registro"}</span></div>`).join("")}<h3>Comparar duas pesagens</h3><div class="fields"><select id="c1">${w.map((r, i) => `<option value="${i}">${date(r.day)} · ${r.kg} kg</option>`).join("")}</select><select id="c2">${w.map((r, i) => `<option value="${i}" ${i === w.length - 1 ? "selected" : ""}>${date(r.day)} · ${r.kg} kg</option>`).join("")}</select></div><p id="difference"></p></div><div><h3>Vacinas e próximas doses</h3>${a.vaccines.length ? a.vaccines.map((v) => `<div class="row"><span><b>${esc(v.name)}</b><br><span class="muted">Aplicação: ${date(v.day)}<br>Próxima: ${date(v.next)}</span></span>${vaccinationBadge(v.next)}</div>`).join("") : "<p>Sem informação de vacinação.</p>"}</div></div><div class="actions">${canManageAnimal() && !a.exit ? '<button id="exit">Registrar saída</button>' : ""}<button id="export-excel">Exportar Excel</button></div>${animalAdminActions()}`;
  const compare = () =>
    ($("#difference").textContent = w.length
      ? `Variação: ${(w[$("#c2").value].kg - w[$("#c1").value].kg).toFixed(1)} kg`
      : "");
  $("#c1").onchange = $("#c2").onchange = compare;
  compare();
  $("#export-excel").onclick = () => download("Animal-"+a.id+".xlsx",animalWorkbook(a),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  if ($("#delete")) $("#delete").onclick = () => confirmDeleteAnimal(a);
  if ($("#exit")) $("#exit").onclick = () => openExit(a);
  if ($("#edit-exit")) $("#edit-exit").onclick = () => openExit(a);
  if ($("#remove-exit")) $("#remove-exit").onclick = () => removeExit(a);
  if ($("#edit"))
    $("#edit").onclick = async () => {
      if (!canManageAnimal()) return;
      if (!(await authorize())) return;
      modal(
        `<h2>Editar ficha e registros</h2><p>Corrija pesos, datas ou vacinas. O brinco é preservado.</p><textarea id="raw" style="width:100%;height:300px">${esc(JSON.stringify(a, null, 2))}</textarea><button id="apply">Salvar alterações</button>`,
      );
      $("#apply").onclick = () => {
        if (!canManageAnimal() || !editUnlocked) return;
        try {
          const x = validateAnimal(JSON.parse($("#raw").value));
          if (x.id !== a.id || x.tagNumber !== a.tagNumber) throw Error("O brinco não pode ser alterado.");
          const previous = db;
          db = {...db, animals: db.animals.map(item => item.id === a.id ? x : item)};
          try { save(); } catch (error) { db = previous; throw error; }
          $("#modal").close();
          $("#search").value = x.tagNumber || x.id;
          if (!x.tagColor && !$("#search-color").querySelector('option[value="sem-cor"]')) {
            $("#search-color").add(new Option("Sem cor registrada", "sem-cor"));
          }
          $("#search-color").value = x.tagColor || "sem-cor";
          lookup(x);
        } catch (error) {
          toast(error instanceof SyntaxError ? "Dados inválidos. Revise os campos." : error.message);
        }
      };
    };
}

function confirmDeleteAnimal(a) {
  if (!canManageAnimal()) return;
  modal(
    `<h2>Excluir todas as informações?</h2><p>Deseja excluir todas as informações do animal <b>${esc(a.id)}</b>?</p><p>Serão apagados o cadastro, as pesagens, as vacinas e o registro de saída. Esta ação não pode ser desfeita pelo site.</p><div class="actions"><button id="confirm-delete-animal" class="danger-button">Excluir animal</button><button id="cancel-delete-animal">Voltar</button></div>`,
  );
  $("#modal-close").hidden = true;
  $("#cancel-delete-animal").onclick = () => $("#modal").close();
  $("#confirm-delete-animal").onclick = async () => {
    if (!canManageAnimal()) return;
    if (!(await authorize())) return;
    if (!canManageAnimal() || !editUnlocked) return;
    const previous = db;
    db = withoutAnimal(db, a.id);
    try {
      save();
      $("#modal").close();
      lookup();
      toast("Animal e todos os seus registros excluídos.");
    } catch {
      db = previous;
      toast("Não foi possível excluir. Tente novamente.");
    }
  };
}

function animalAdminActions() {
  if (!canManageAnimal()) return "";
  return `<div class="animal-admin-actions" aria-label="Administração do animal"><button id="edit" class="admin-icon" title="Editar ficha" aria-label="Editar ficha"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m9 3-.5 2-2 1-2-.5-2 3.5 1.5 1.5v3L2.5 15l2 3.5 2-.5 2 1 .5 2h4l.5-2 2-1 2 .5 2-3.5-1.5-1.5v-3L20 9l-2-3.5-2 .5-2-1-.5-2Z"/><circle cx="11.3" cy="12" r="3"/></svg></button><button id="delete" class="admin-icon" title="Excluir animal" aria-label="Excluir animal"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div>`;
}

// Pacote ZIP sem compressão para leitura offline do arquivo XLSX.
function excelZip(files) {
  const encoder = new TextEncoder();
  const parts = [], directory = [];
  let offset = 0;
  function header(size) {
    const bytes = new Uint8Array(size);
    const view = new DataView(bytes.buffer);
    return {bytes, word:(i,n)=>view.setUint16(i,n,true), long:(i,n)=>view.setUint32(i,n,true)};
  }
  for (const [path,xml] of Object.entries(files)) {
    const name = encoder.encode(path), data = encoder.encode(xml);
    let crc = -1;
    for (const byte of data) {
      crc ^= byte;
      for (let i=0;i<8;i++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
    }
    const local = header(30), central = header(46);
    local.long(0,0x04034b50); local.word(4,20); local.long(14,~crc);
    local.long(18,data.length); local.long(22,data.length); local.word(26,name.length);
    central.long(0,0x02014b50); central.word(4,20); central.word(6,20); central.long(16,~crc);
    central.long(20,data.length); central.long(24,data.length); central.word(28,name.length); central.long(42,offset);
    parts.push(local.bytes,name,data); directory.push(central.bytes,name);
    offset += local.bytes.length + name.length + data.length;
  }
  const end = header(22), count = directory.length/2;
  end.long(0,0x06054b50); end.word(8,count); end.word(10,count);
  end.long(12,directory.reduce((sum,item)=>sum+item.length,0)); end.long(16,offset);
  return new Blob([...parts,...directory,end.bytes]);
}

function animalSheets(a) {

  const day = v => v ? date(v) : '';
  const sheets = {
    Cadastro:[['Campo','Informação'],['Brinco',a.tagNumber||a.id],['Identificador da ficha',a.id],['Cor do brinco',a.tagColor],['Idade (em meses)',a.age],['Sexo',a.sex],['Raça',a.breed],['Data de entrada',day(a.arrival)],['Origem',a.origin],['Propriedade de origem',a.from],['Preço do kg de entrada (R$)',hasInfo(a.entryPriceKg)?Number(a.entryPriceKg):''],['Lotes',animalLots(a).join(', ')],['Situação',statusLabel(animalStatus(a))]],
    Pesagens:[['Data','Peso (kg)','Momento do registro'],...a.weights.map(r=>[day(r.day),r.kg,r.time])],
    Vacinas:[['Data de aplicação','Vacina','Próxima dose'],...a.vaccines.map(v=>[day(v.day),v.name,day(v.next)])],
    Banhos:[['Data do banho'],...(a.baths||[]).map(r=>[day(r.day)])],
    Movimentações:[['Evento','Data','Tipo','Motivo ou detalhe','Destinatário ou origem','Valor (R$)','Preço do kg (R$)']]
  };
  function movement(label,r) {
    if (r) sheets.Movimentações.push([label,day(r.day),r.type||r.reason,r.detail||r.transferReason||(r.type?r.reason:''),r.recipient||r.from,r.amount,r.priceKg]);
  }
  for (const m of a.movements||[]) {movement('Saída',m.exit); movement('Retorno',m.return);}
  movement('Saída atual',a.exit);
  return sheets;
}

function animalWorkbook(a) {
  const sheets = animalSheets(a);
  const day = v => v ? date(v) : '';
  const history = [
    ...a.weights.map(r => [r.day, 'Pesagem', r.kg, '', '', r.time]),
    ...(a.baths || []).map(r => [r.day, 'Banho']),
    ...a.vaccines.map(r => [r.day, 'Vacinação', '', r.name, day(r.next)])
  ].sort((left, right) => left[0].localeCompare(right[0]));
  sheets.Cadastro.push([], ['Histórico de manejo'], ['Data', 'Registro', 'Peso (kg)', 'Vacina', 'Próxima dose', 'Momento do registro']);
  for (const [when, ...details] of history) sheets.Cadastro.push([day(when), ...details]);
  if (!history.length) sheets.Cadastro.push(['Nenhuma pesagem, banho ou vacinação registrada.']);
  return workbook(sheets);
}

