function workbook(sheets) {
  const text = v => esc(String(v ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g,''));
  const ns='http://schemas.openxmlformats.org/', rel=ns+'officeDocument/2006/relationships', main=ns+'spreadsheetml/2006/main';
  const names=Object.keys(sheets);
  const format = excelLayouts[names[0]];
  const relationships=items=>'<Relationships xmlns="'+ns+'package/2006/relationships">'+items.map(([id,type,target])=>'<Relationship Id="'+id+'" Type="'+rel+'/'+type+'" Target="'+target+'"/>').join('')+'</Relationships>';
  const files={
    '[Content_Types].xml':'<Types xmlns="'+ns+'package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/xl/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+names.map((_,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'</Types>',
    '_rels/.rels':relationships([['r1','officeDocument','xl/workbook.xml']]),
    'xl/workbook.xml':'<workbook xmlns="'+main+'" xmlns:r="'+rel+'"><sheets>'+names.map((n,i)=>'<sheet name="'+n+'" sheetId="'+(i+1)+'" r:id="r'+(i+1)+'"/>').join('')+'</sheets></workbook>',
    'xl/_rels/workbook.xml.rels':relationships([...names.map((_,i)=>['r'+(i+1),'worksheet','worksheets/sheet'+(i+1)+'.xml']), ['styles','styles','styles.xml'], ['theme','theme','theme/theme1.xml']]),
    'xl/styles.xml':format.styles,
    'xl/theme/theme1.xml':format.theme
  };
  names.forEach((name,i)=>{
    const rows=sheets[name];
    const layout = format.sheets[name];
    const data = rows.slice();
    if (data.length === 1) data.push([]);
    const sheetData = data.map((row,index) => {
      const styles = layout.prefix[index] ?? (index === data.length - 1 ? layout.last :
        index === layout.prefix.length ? layout.first : layout.body);
      const cells = Array.from({length:Math.max(row.length,styles.length)}, (_,col) => {
        const value = row[col];
        const attrs = ' r="'+String.fromCharCode(65+col)+(index+1)+'" s="'+(styles[col] || 0)+'"';
        if (value == null || value === '') return '<c'+attrs+'/>';
        if (typeof value === 'number') return '<c'+attrs+'><v>'+value+'</v></c>';
        return '<c'+attrs+' t="inlineStr"><is><t xml:space="preserve">'+text(value)+'</t></is></c>';
      });
      return '<row r="'+(index+1)+'"'+(index>=20?' ht="15.75" customHeight="1"':'')+'>'+cells.join('')+'</row>';
    });
    files['xl/worksheets/sheet'+(i+1)+'.xml']='<worksheet xmlns="'+main+'">'+layout.layout+'<sheetData>'+sheetData.join('')+'</sheetData></worksheet>';
  });
  return excelZip(files);
}
